import openpyxl

wb = openpyxl.load_workbook('sales_data.xlsx')
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\nSheet: {name} | dims: {ws.dimensions} | max_row: {ws.max_row} | max_col: {ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 15)):
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {repr(cell.value)}")

import importlib
for mod in ['pandas', 'openpyxl', 'xlrd', 'xlsxwriter']:
    try:
        importlib.import_module(mod)
        print(mod, "OK")
    except ImportError as e:
        print(mod, "MISSING")

